import type { MedicalIncidentAttachment } from './MedicalIncident';

export const IncidentPublicReportStatus = {
  Submitted: 'submitted',
  Confirmed: 'confirmed',
  Rejected: 'rejected',
} as const;

export type IncidentPublicReportStatusValue =
  (typeof IncidentPublicReportStatus)[keyof typeof IncidentPublicReportStatus];

export const IncidentPublicReporterKind = {
  Patient: 'patient',
  Family: 'family',
} as const;

export type IncidentPublicReporterKindValue =
  (typeof IncidentPublicReporterKind)[keyof typeof IncidentPublicReporterKind];

export interface IncidentPublicReport {
  id: string;
  idCode: string;
  reporterKind: IncidentPublicReporterKindValue | string;
  reporterName: string;
  reporterPhone: string;
  patientName: string;
  patientGender: string;
  departmentId: string;
  departmentName: string;
  areaText: string | null;
  occurredAt: string;
  description: string;
  status: IncidentPublicReportStatusValue | string;
  deviceId: string | null;
  confirmedById: string | null;
  confirmedByName: string | null;
  confirmedAt: string | null;
  incidentId: string | null;
  incidentIdCode: string | null;
  rejectReason: string | null;
  createdAt: string;
  updatedAt: string;
  attachments?: MedicalIncidentAttachment[];
}

export interface IncidentPublicReportFilters {
  search?: string;
  status?: string;
  departmentId?: string;
}

export interface IncidentPublicReportStats {
  total: number;
  submitted: number;
  confirmed: number;
  rejected: number;
}

export interface IncidentPublicReportGuestInit {
  companyCode: string;
  companyName: string;
  departments: { id: string; name: string; code?: string }[];
  patientGenders: { value: string; label: string }[];
  reporterKinds: { value: string; label: string }[];
  statuses: { value: string; label: string }[];
  labels: { value: string; label: string }[];
}

export interface IncidentPublicReportPoster {
  companyCode: string;
  companyName: string;
  path: string;
}

export function createEmptyPublicReport(): Partial<IncidentPublicReport> {
  return {
    reporterKind: IncidentPublicReporterKind.Patient,
    reporterName: '',
    reporterPhone: '',
    patientName: '',
    patientGender: '',
    departmentId: '',
    departmentName: '',
    areaText: '',
    occurredAt: new Date().toISOString(),
    description: '',
  };
}
